# -*- coding: utf-8 -*-
simulators = {1: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🧬</span> Accumulation of Variation Across Generations\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Compare subtle copying inaccuracies in asexual division with diverse sexual recombination</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="setSlide1Mode(\'asexual\')" id="btnSlide1Asexual" class="px-3 py-1.5 rounded-xl bg-cyan-600 text-white text-xs font-semibold shadow-md transition-all">\n                    Asexual (Sugarcane / Bacteria)\n                </button>\n                <button onclick="setSlide1Mode(\'sexual\')" id="btnSlide1Sexual" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold border border-slate-700 transition-all">\n                    Sexual (High Diversity)\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide1Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="flex flex-wrap items-center justify-between gap-2 pt-1 border-t border-slate-800/80">\n            <div class="flex items-center gap-2">\n                <span class="text-xs text-slate-400 font-medium">Generation:</span>\n                <span id="slide1GenBadge" class="px-2.5 py-0.5 rounded-full bg-slate-800 text-cyan-400 text-xs font-bold border border-cyan-500/20">Gen 1</span>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="stepSlide1Gen()" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-xs font-medium text-slate-200 border border-slate-700 transition-all">\n                    Next Generation (Reproduction)\n                </button>\n                <button onclick="resetSlide1()" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-xs font-medium text-slate-400 border border-slate-700 transition-all">\n                    Reset\n                </button>\n            </div>\n        </div>\n\n        <div id="slide1Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            In asexual reproduction, 1 individual divides into 2 with almost identical design; subtle variations accumulate very slowly over generations due to minor DNA copying inaccuracies.\n        </div>\n    </div>\n    ', 2: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🔬</span> DNA Replication & Copying Inaccuracies\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Observe complementary base pairing and nucleotide mismatch variations</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="replicateSlide2DNA()" class="px-3 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Replicate DNA Fork\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide2Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1 border-t border-slate-800/80">\n            <div>\n                <label class="block text-xs font-medium text-slate-400 mb-1">Copying Fidelity / Mutation Rate:</label>\n                <input type="range" id="slide2FidelitySlider" min="1" max="3" value="2" oninput="setSlide2Fidelity(this.value)" class="w-full accent-indigo-500 cursor-pointer">\n                <div class="flex justify-between text-[10px] text-slate-500 mt-0.5">\n                    <span>Ultra-High (99.9%)</span>\n                    <span class="text-indigo-400 font-semibold">Normal (99.0%)</span>\n                    <span>High Mutation (95%)</span>\n                </div>\n            </div>\n            <div id="slide2Stats" class="p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs text-slate-300 flex items-center justify-around">\n                <span>Matching Bases: <strong class="text-emerald-400" id="slide2Matches">24/24</strong></span>\n                <span>Mismatches: <strong class="text-amber-400" id="slide2Errors">0</strong></span>\n            </div>\n        </div>\n\n        <div id="slide2Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            DNA replication is highly precise (A pairs with T, G pairs with C), but occasional biochemical slip-ups introduce single nucleotide variants that serve as the raw material for variation.\n        </div>\n    </div>\n    ', 3: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🌡️</span> Environmental Selection of Advantageous Variants\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Simulate a heat wave acting on heat-sensitive vs heat-resistant bacterial variants</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="applySlide3HeatWave()" class="px-3 py-1.5 rounded-xl bg-rose-600 hover:bg-rose-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Trigger Heat Wave (65°C)\n                </button>\n                <button onclick="resetSlide3Culture()" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold border border-slate-700 transition-all">\n                    Reset Culture\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide3Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1 border-t border-slate-800/80">\n            <div>\n                <label class="block text-xs font-medium text-slate-400 mb-1">Ambient Water Temperature: <span id="slide3TempDisplay" class="text-amber-400 font-bold">30°C</span></label>\n                <input type="range" id="slide3TempSlider" min="20" max="75" value="30" oninput="setSlide3Temp(this.value)" class="w-full accent-rose-500 cursor-pointer">\n            </div>\n            <div class="flex items-center justify-between p-2 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300">\n                <span class="flex items-center gap-1.5"><span class="w-3 h-3 rounded-full bg-emerald-500 inline-block"></span> Normal (<span id="slide3NormalCount">45</span>)</span>\n                <span class="flex items-center gap-1.5"><span class="w-3 h-3 rounded-full bg-rose-500 inline-block"></span> Heat-Resistant (<span id="slide3ResistantCount">5</span>)</span>\n            </div>\n        </div>\n\n        <div id="slide3Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            In moderate temperatures (30°C), normal bacteria thrive. When water temperature surges past 55°C, normal bacteria perish while heat-resistant variants survive and multiply, demonstrating natural selection.\n        </div>\n    </div>\n    ', 4: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>👥</span> Equal Parental Contribution in Heredity\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Explore how maternal and paternal gametes each contribute one set of genes</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="fuseSlide4Gametes()" class="px-3 py-1.5 rounded-xl bg-teal-600 hover:bg-teal-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Fuse Gametes (Fertilization)\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide4Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="flex flex-wrap items-center justify-between gap-2 pt-1 border-t border-slate-800/80">\n            <div class="flex items-center gap-2">\n                <span class="text-xs text-slate-400">Select Character:</span>\n                <select id="slide4TraitSelect" onchange="setSlide4Trait(this.value)" class="bg-slate-900 border border-slate-700 text-xs text-slate-200 rounded-lg px-2.5 py-1 focus:ring-1 focus:ring-teal-500">\n                    <option value="height">Plant Height (Tall \'T\' / Dwarf \'t\')</option>\n                    <option value="seed">Seed Shape (Round \'R\' / Wrinkled \'r\')</option>\n                    <option value="earlobe">Human Earlobe (Free \'E\' / Attached \'e\')</option>\n                </select>\n            </div>\n            <span id="slide4GenotypeBadge" class="text-xs font-mono font-bold text-teal-400 px-3 py-1 rounded-full bg-slate-900 border border-teal-500/30">\n                Ploidy: Diploid (2n)\n            </span>\n        </div>\n\n        <div id="slide4Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            Both parents contribute equal amounts of genetic material. Offspring inherit two copies of each gene: one maternal allele via the ovum and one paternal allele via the sperm.\n        </div>\n    </div>\n    ', 5: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>👂</span> Inherited Human Traits: Earlobe Survey (Activity 8.1)\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Survey free earlobes (hanging) vs attached earlobes (fused) in a population</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="sampleSlide5Earlobes(40)" class="px-3 py-1.5 rounded-xl bg-amber-600 hover:bg-amber-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Survey Class (40)\n                </button>\n                <button onclick="sampleSlide5Earlobes(200)" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold border border-slate-700 transition-all">\n                    Large School (200)\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide5Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1 border-t border-slate-800/80 text-center">\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Total Surveyed</span>\n                <span id="slide5Total" class="text-sm font-bold text-white">40</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-amber-500/30">\n                <span class="block text-[10px] text-amber-300">Free Earlobes</span>\n                <span id="slide5Free" class="text-sm font-bold text-amber-400">30 (75%)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-700">\n                <span class="block text-[10px] text-slate-400">Attached Earlobes</span>\n                <span id="slide5Attached" class="text-sm font-bold text-slate-200">10 (25%)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Dominant Trait</span>\n                <span class="text-sm font-bold text-emerald-400">Free (E)</span>\n            </div>\n        </div>\n\n        <div id="slide5Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            In human populations, free earlobes are far more common because the free earlobe allele is dominant, while attached earlobes require two copies of the recessive allele.\n        </div>\n    </div>\n    ', 6: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🌱</span> Mendel\'s Pea Breeding Bench (Pisum sativum)\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Explore the 7 contrasting pairs of characters and controlled cross-pollination</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="pollinateSlide6Peas()" class="px-3 py-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Cross-Pollinate Flowers\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide6Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="flex flex-wrap items-center justify-between gap-2 pt-1 border-t border-slate-800/80">\n            <div class="flex items-center gap-2">\n                <span class="text-xs text-slate-400">Mendelian Trait:</span>\n                <select id="slide6TraitSelect" onchange="setSlide6PeaTrait(this.value)" class="bg-slate-900 border border-slate-700 text-xs text-slate-200 rounded-lg px-2.5 py-1 focus:ring-1 focus:ring-emerald-500">\n                    <option value="height">Plant Height: Tall vs Dwarf</option>\n                    <option value="seed_shape">Seed Shape: Round vs Wrinkled</option>\n                    <option value="seed_color">Seed Color: Yellow vs Green</option>\n                    <option value="flower_color">Flower Color: Violet vs White</option>\n                    <option value="pod_shape">Pod Shape: Inflated vs Constricted</option>\n                </select>\n            </div>\n            <span id="slide6DomBadge" class="text-xs text-emerald-400 font-semibold px-2.5 py-0.5 rounded-full bg-slate-900 border border-emerald-500/20">\n                Dominant vs Recessive Pair\n            </span>\n        </div>\n\n        <div id="slide6Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            Mendel chose garden peas because they have distinct contrasting traits, reproduce rapidly, and can be artificially cross-pollinated by dusting pollen onto emasculated flowers.\n        </div>\n    </div>\n    ', 7: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🪴</span> Monohybrid Cross: Tall × Short Pea Plants\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Track parental cross, uniform F1 progeny, and the 3:1 ratio in the F2 generation</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="setSlide7Stage(\'P\')" id="btnSlide7P" class="px-2.5 py-1 rounded-lg bg-emerald-600 text-white text-xs font-semibold">Parental (P)</button>\n                <button onclick="setSlide7Stage(\'F1\')" id="btnSlide7F1" class="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300 text-xs hover:bg-slate-700">F1 Progeny</button>\n                <button onclick="setSlide7Stage(\'F2\')" id="btnSlide7F2" class="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300 text-xs hover:bg-slate-700">F2 Selfing</button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide7Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-3 gap-2 pt-1 border-t border-slate-800/80 text-center">\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Current Generation</span>\n                <span id="slide7CurrentGen" class="text-xs font-bold text-emerald-400">Parental (TT × tt)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Tall Plants</span>\n                <span id="slide7TallCount" class="text-xs font-bold text-white">50% (P)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Dwarf Plants</span>\n                <span id="slide7ShortCount" class="text-xs font-bold text-white">50% (P)</span>\n            </div>\n        </div>\n\n        <div id="slide7Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            In the parental cross, pure tall (TT) crosses with pure short (tt). The F1 generation is 100% tall (Tt). When F1 self-pollinates, the F2 generation yields exactly 3 tall : 1 short!\n        </div>\n    </div>\n    ', 8: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🔲</span> Punnett Square & Allelic Dominance Calculator\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Determine genotypic (1:2:1) and phenotypic (3:1) distributions</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <select id="slide8CrossSelect" onchange="updateSlide8Cross(this.value)" class="bg-slate-900 border border-slate-700 text-xs text-slate-200 rounded-lg px-2.5 py-1 focus:ring-1 focus:ring-purple-500">\n                    <option value="Tt_Tt">F1 Selfing: Tt × Tt (Heterozygous)</option>\n                    <option value="TT_tt">Parental Cross: TT × tt</option>\n                    <option value="Tt_tt">Test Cross: Tt × tt</option>\n                </select>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide8Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-2 gap-3 pt-1 border-t border-slate-800/80">\n            <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400 uppercase tracking-wider font-semibold">Phenotype Ratio</span>\n                <span id="slide8PhenoRatio" class="text-sm font-bold text-purple-400">3 Tall : 1 Dwarf (75% vs 25%)</span>\n            </div>\n            <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400 uppercase tracking-wider font-semibold">Genotype Ratio</span>\n                <span id="slide8GenoRatio" class="text-sm font-bold text-cyan-400">1 TT : 2 Tt : 1 tt (25% : 50% : 25%)</span>\n            </div>\n        </div>\n\n        <div id="slide8Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            The Punnett square displays all 4 gametic combinations. Because allele \'T\' is dominant, both \'TT\' and \'Tt\' develop as tall plants, creating the classic 3:1 phenotypic ratio.\n        </div>\n    </div>\n    ', 9: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🟡</span> Dihybrid Cross: Round Yellow × Wrinkled Green\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Track simultaneous inheritance of two traits: seed shape and seed color</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="crossSlide9Parents()" class="px-3 py-1.5 rounded-xl bg-amber-600 hover:bg-amber-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Perform Dihybrid Cross\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide9Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-2 sm:grid-cols-3 gap-2 pt-1 border-t border-slate-800/80 text-center">\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Parent 1 (Dominant)</span>\n                <span class="text-xs font-bold text-amber-400">Round Yellow (RRYY)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Parent 2 (Recessive)</span>\n                <span class="text-xs font-bold text-emerald-400">Wrinkled Green (rryy)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-amber-500/30 col-span-2 sm:col-span-1">\n                <span class="block text-[10px] text-slate-400">F1 Generation</span>\n                <span class="text-xs font-bold text-white">100% Round Yellow (RrYy)</span>\n            </div>\n        </div>\n\n        <div id="slide9Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            Gametes from RRYY carry \'RY\' and gametes from rryy carry \'ry\'. All F1 offspring inherit the heterozygous genotype RrYy, producing 100% round yellow seeds because R and Y are completely dominant!\n        </div>\n    </div>\n    ', 10: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🎲</span> Law of Independent Assortment (16-Cell Punnett Grid)\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Explore the 9:3:3:1 phenotypic ratio and appearance of new recombinant traits</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="filterSlide10Seeds(\'all\')" id="btnSlide10All" class="px-2.5 py-1 rounded-lg bg-indigo-600 text-white text-xs font-semibold">All 16</button>\n                <button onclick="filterSlide10Seeds(\'parental\')" id="btnSlide10Parental" class="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300 text-xs hover:bg-slate-700">Parentals (10)</button>\n                <button onclick="filterSlide10Seeds(\'recombinant\')" id="btnSlide10Recomb" class="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300 text-xs hover:bg-slate-700">Recombinants (6)</button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide10Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-4 gap-2 pt-1 border-t border-slate-800/80 text-center">\n            <div class="p-2 rounded-xl bg-slate-900 border border-amber-500/30">\n                <span class="block text-[10px] text-amber-300">Round Yellow</span>\n                <span id="slide10RY" class="text-sm font-bold text-white">9 / 16</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-emerald-500/30">\n                <span class="block text-[10px] text-emerald-300">Round Green</span>\n                <span id="slide10RG" class="text-sm font-bold text-emerald-400">3 / 16 (New)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-yellow-500/30">\n                <span class="block text-[10px] text-yellow-300">Wrinkled Yellow</span>\n                <span id="slide10WY" class="text-sm font-bold text-yellow-400">3 / 16 (New)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-teal-500/30">\n                <span class="block text-[10px] text-teal-300">Wrinkled Green</span>\n                <span id="slide10WG" class="text-sm font-bold text-teal-400">1 / 16</span>\n            </div>\n        </div>\n\n        <div id="slide10Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            The appearance of round green (3) and wrinkled yellow (3) seeds demonstrates that seed shape and seed color assort independently during gamete formation, confirming Mendel\'s Law of Independent Assortment.\n        </div>\n    </div>\n    ', 11: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🧬</span> Gene Expression: DNA to Functional Protein\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Cellular DNA contains coding segments (genes) that direct protein synthesis</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="transcribeSlide11Gene()" class="px-3 py-1.5 rounded-xl bg-cyan-600 hover:bg-cyan-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Transcribe & Translate\n                </button>\n                <button onclick="toggleSlide11Mutation()" id="btnSlide11Mut" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold border border-slate-700 transition-all">\n                    Mutate Gene Segment\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide11Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-3 gap-2 pt-1 border-t border-slate-800/80 text-center">\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">DNA Gene Code</span>\n                <span id="slide11DNACode" class="text-xs font-mono font-bold text-cyan-400">TAC-GGC-TTA-ACT</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">mRNA Transcript</span>\n                <span id="slide11RNACode" class="text-xs font-mono font-bold text-emerald-400">AUG-CCG-AAU-UGA</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Protein Activity</span>\n                <span id="slide11ProteinStatus" class="text-xs font-bold text-emerald-400">Active Enzyme (100%)</span>\n            </div>\n        </div>\n\n        <div id="slide11Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            Cellular DNA stores information for proteins. A gene is transcribed into mRNA, which translates into an amino acid sequence forming an enzyme that controls cellular biochemical reactions.\n        </div>\n    </div>\n    ', 12: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🌿</span> Enzyme Efficiency & Plant Growth Hormone\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Observe how gene-controlled enzyme efficiency governs tall vs dwarf plant height</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="setSlide12EnzymeLevel(100)" class="px-2.5 py-1 rounded-lg bg-emerald-600 text-white text-xs font-semibold">Tall (100% Enzyme)</button>\n                <button onclick="setSlide12EnzymeLevel(20)" class="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300 text-xs hover:bg-slate-700">Dwarf (20% Enzyme)</button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide12Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1 border-t border-slate-800/80">\n            <div>\n                <label class="block text-xs font-medium text-slate-400 mb-1">Enzyme Catalytic Efficiency: <span id="slide12EffDisplay" class="text-emerald-400 font-bold">100%</span></label>\n                <input type="range" id="slide12Slider" min="10" max="100" value="100" oninput="setSlide12EnzymeSlider(this.value)" class="w-full accent-emerald-500 cursor-pointer">\n            </div>\n            <div class="flex items-center justify-between p-2 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300">\n                <span>Hormone Synthesized: <strong id="slide12HormoneLevel" class="text-emerald-400">High (100 ppm)</strong></span>\n                <span>Phenotype: <strong id="slide12Phenotype" class="text-white">Tall Plant</strong></span>\n            </div>\n        </div>\n\n        <div id="slide12Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            The dominant gene \'T\' produces an efficient enzyme that synthesizes abundant growth hormone, resulting in tall plants. An altered \'t\' gene produces a less efficient enzyme, synthesizing little hormone, leaving the plant dwarf.\n        </div>\n    </div>\n    ', 13: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🔬</span> Chromosomal Mechanism of Heredity & Meiosis\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Homologous chromosome pairing, meiotic reduction division & fertilization restoration</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="runSlide13Meiosis()" class="px-3 py-1.5 rounded-xl bg-purple-600 hover:bg-purple-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Perform Meiosis (Reduction)\n                </button>\n                <button onclick="fuseSlide13Gametes()" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold border border-slate-700 transition-all">\n                    Fertilize Zygote\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide13Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-3 gap-2 pt-1 border-t border-slate-800/80 text-center">\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Somatic Body Cell</span>\n                <span class="text-xs font-bold text-purple-400">Diploid (2n = 46 chr)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Germ Cell / Gamete</span>\n                <span id="slide13GametePloidy" class="text-xs font-bold text-cyan-400">Haploid (n = 23 chr)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Zygote State</span>\n                <span id="slide13ZygotePloidy" class="text-xs font-bold text-white">Restored Diploid (2n)</span>\n            </div>\n        </div>\n\n        <div id="slide13Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            Genes reside on discrete chromosomes organized in pairs. Meiotic cell division separates chromosome pairs so each gamete receives only one, and fertilization reunites them to restore the diploid number.\n        </div>\n    </div>\n    ', 14: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🦎</span> Environmental vs Genetic Sex Determination\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Explore temperature cues in reptiles, sex change in snails, and genetic cues in humans</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <select id="slide14SpeciesSelect" onchange="setSlide14Species(this.value)" class="bg-slate-900 border border-slate-700 text-xs text-slate-200 rounded-lg px-2.5 py-1 focus:ring-1 focus:ring-amber-500">\n                    <option value="reptile">Reptiles: Incubation Temperature (Turtle / Crocodile)</option>\n                    <option value="snail">Garden Snail: Flexible Non-Genetic Sex Change</option>\n                    <option value="human">Humans: Strictly Genetic (XX / XY)</option>\n                </select>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide14Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div id="slide14ControlArea" class="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1 border-t border-slate-800/80">\n            <div>\n                <label class="block text-xs font-medium text-slate-400 mb-1">Nest Incubation Temperature: <span id="slide14TempDisplay" class="text-amber-400 font-bold">29°C</span></label>\n                <input type="range" id="slide14TempSlider" min="24" max="34" value="29" oninput="setSlide14Temp(this.value)" class="w-full accent-amber-500 cursor-pointer">\n            </div>\n            <div class="flex items-center justify-between p-2 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300">\n                <span>Determined Sex: <strong id="slide14SexOutput" class="text-cyan-400">Mixed (50% M / 50% F)</strong></span>\n                <span>Mechanism: <strong class="text-white">Environmental Cue</strong></span>\n            </div>\n        </div>\n\n        <div id="slide14Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            In some reptiles, cool incubation temperatures produce males while warm temperatures produce females. In contrast, human sex is strictly genetic and established at fertilization.\n        </div>\n    </div>\n    ', 15: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>🗂️</span> Human Karyotype: 22 Autosomes + Sex Chromosomes\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Inspect the 23 chromosome pairs: Perfect XX female vs mismatched XY male</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="setSlide15Karyotype(\'female\')" id="btnSlide15Female" class="px-3 py-1.5 rounded-xl bg-pink-600 text-white text-xs font-semibold shadow-md transition-all">\n                    Female (44 + XX)\n                </button>\n                <button onclick="setSlide15Karyotype(\'male\')" id="btnSlide15Male" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold border border-slate-700 transition-all">\n                    Male (44 + XY)\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide15Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-3 gap-2 pt-1 border-t border-slate-800/80 text-center">\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Autosomal Pairs</span>\n                <span class="text-xs font-bold text-slate-200">22 Pairs (Identical M/F)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">23rd Sex Pair</span>\n                <span id="slide15SexPairBadge" class="text-xs font-bold text-pink-400">XX (Homogametic)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Gametes Produced</span>\n                <span id="slide15GameteBadge" class="text-xs font-bold text-emerald-400">100% X-bearing Eggs</span>\n            </div>\n        </div>\n\n        <div id="slide15Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            Human females have two full-sized X chromosomes (XX). Human males have a mismatched pair: one full-sized X and a noticeably shorter Y chromosome (XY).\n        </div>\n    </div>\n    ', 16: '\n    <div class="bg-slate-950/80 border border-slate-800 rounded-2xl p-4 sm:p-5 space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm sm:text-base font-bold text-white flex items-center gap-2">\n                    <span>👶</span> Sex Inheritance Probability & Paternal Determination\n                </h3>\n                <p class="text-xs text-slate-400 mt-0.5">Punnett square analysis demonstrating exact 50-50 odds and father\'s genetic role</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <button onclick="simulateSlide16Birth(1)" class="px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-500 text-white text-xs font-semibold shadow-md transition-all">\n                    Conceive Child\n                </button>\n                <button onclick="simulateSlide16Batch(20)" class="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold border border-slate-700 transition-all">\n                    Simulate 20 Births\n                </button>\n                <button onclick="resetSlide16Stats()" class="px-2.5 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-400 text-xs border border-slate-700 transition-all">\n                    Reset\n                </button>\n            </div>\n        </div>\n\n        <div class="relative w-full aspect-[16/9] max-h-[340px] bg-slate-900/90 rounded-xl overflow-hidden border border-slate-800 flex items-center justify-center">\n            <canvas id="slide16Canvas" width="600" height="340" class="w-full h-full object-contain"></canvas>\n        </div>\n\n        <div class="grid grid-cols-4 gap-2 pt-1 border-t border-slate-800/80 text-center">\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Total Children</span>\n                <span id="slide16TotalCount" class="text-sm font-bold text-white">0</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-pink-500/30">\n                <span class="block text-[10px] text-pink-300">Girls (XX)</span>\n                <span id="slide16GirlCount" class="text-sm font-bold text-pink-400">0 (50%)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-blue-500/30">\n                <span class="block text-[10px] text-blue-300">Boys (XY)</span>\n                <span id="slide16BoyCount" class="text-sm font-bold text-blue-400">0 (50%)</span>\n            </div>\n            <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                <span class="block text-[10px] text-slate-400">Paternal Role</span>\n                <span class="text-xs font-bold text-emerald-400">Sperm Decides Sex</span>\n            </div>\n        </div>\n\n        <div id="slide16Status" class="p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 leading-relaxed">\n            Mothers only contribute X chromosomes. The father produces 50% X-bearing and 50% Y-bearing sperm. Therefore, the father\'s fertilizing sperm alone genetically determines the child\'s sex with an exact 50% probability!\n        </div>\n    </div>\n    '}
